import re, urllib.request, urllib.parse, urllib.error, collections
BASE = "https://firstrun.atharvashah.com/"
seen = {}
queue = collections.deque([BASE])
ext = set()
bad = []

def get(u, m="GET"):
    r = urllib.request.Request(u, method=m, headers={"User-Agent": "Mozilla/5.0 qa"})
    try:
        with urllib.request.urlopen(r, timeout=30) as x:
            return x.status, x.read(), x.headers.get("content-type", "")
    except urllib.error.HTTPError as e:
        return e.code, b"", ""
    except Exception as e:
        return str(e), b"", ""

while queue:
    u = queue.popleft().split("#")[0]
    if u in seen:
        continue
    s, b, ct = get(u)
    seen[u] = s
    if s != 200:
        bad.append((u, s))
        continue
    if "html" in ct or "css" in ct or u.endswith(".js"):
        t = b.decode("utf8", "ignore")
        for m in re.findall(r'(?:href|src|poster)=["\']([^"\']+)["\']|url\(["\']?([^)"\']+)', t):
            l = m[0] or m[1]
            if l.startswith(("mailto:", "javascript:", "data:", "#", "tel:")):
                continue
            f = urllib.parse.urljoin(u, l).split("#")[0]
            if f.startswith(BASE):
                if f not in seen:
                    queue.append(f)
            elif f.startswith("http"):
                ext.add(f)
print("internal checked", len(seen))
print("non200", bad)
for e in sorted(ext):
    s, _, _ = get(e, "HEAD")
    if s in (405, 403, 400, 999):
        s, _, _ = get(e)
    print(s, e)

